class ValidationError(Exception):
    def __init__(self, field, message):
        self.field = field
        self.message = message


class HTTPException(Exception):
    def __init__(self, status_code, detail):
        self.status_code = status_code
        self.detail = detail


def validate_item(data):
    if data.get("price", 0) <= 0:
        raise ValidationError("price", "must be greater than 0")
    if data.get("quantity", 0) < 1:
        raise ValidationError("quantity", "must be at least 1")
    return data


def create_item(data):
    item = validate_item(data)
    return {"status": 201, "data": item}


def get_item(item_id, catalog):
    if item_id not in catalog:
        raise HTTPException(404, "item not found")
    return {"status": 200, "data": catalog[item_id]}


def run(handler, *args):
    try:
        return handler(*args)
    except ValidationError as exc:
        return {"status": 422, "error": {"field": exc.field, "message": exc.message}}
    except HTTPException as exc:
        return {"status": exc.status_code, "error": exc.detail}


catalog = {1: {"id": 1, "price": 9.99}}
print(run(create_item, {"price": 9.99, "quantity": 2}))
print(run(create_item, {"price": -1, "quantity": 2}))
print(run(get_item, 1, catalog))
print(run(get_item, 5, catalog))
